PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, firebase_uid TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL DEFAULT '', phone TEXT, avatar_url TEXT, bio TEXT, role TEXT NOT NULL DEFAULT 'buyer' CHECK(role IN ('buyer','seller','admin')), account_status TEXT NOT NULL DEFAULT 'active' CHECK(account_status IN ('active','suspended','deleted')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_users_role_status ON users(role,account_status);
CREATE TABLE IF NOT EXISTS seller_applications (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),legal_name TEXT NOT NULL,phone TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),reviewed_by TEXT REFERENCES users(id),reviewed_at TEXT,review_note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id));
CREATE INDEX IF NOT EXISTS idx_seller_apps_status ON seller_applications(status,created_at);
CREATE TABLE IF NOT EXISTS tip_listings (id TEXT PRIMARY KEY,seller_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',sport TEXT NOT NULL DEFAULT 'football',price_tzs INTEGER NOT NULL CHECK(price_tzs>=0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending_review','published','rejected','archived')),result_status TEXT NOT NULL DEFAULT 'pending' CHECK(result_status IN ('pending','won','lost','void','partial')),published_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_listings_status_created ON tip_listings(status,created_at);
CREATE TABLE IF NOT EXISTS listing_selections (id TEXT PRIMARY KEY,listing_id TEXT NOT NULL REFERENCES tip_listings(id) ON DELETE CASCADE,fixture_external_id TEXT,home_name TEXT NOT NULL,away_name TEXT NOT NULL,market TEXT NOT NULL,selection TEXT NOT NULL,odds_decimal REAL,odds_source TEXT,odds_updated_at TEXT,result_status TEXT NOT NULL DEFAULT 'pending' CHECK(result_status IN ('pending','won','lost','void')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS social_posts (id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 5000),visibility TEXT NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','followers')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_posts_created ON social_posts(created_at DESC);
CREATE TABLE IF NOT EXISTS post_likes (post_id TEXT NOT NULL REFERENCES social_posts(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(post_id,user_id));
CREATE TABLE IF NOT EXISTS post_comments (id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES social_posts(id) ON DELETE CASCADE,author_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 2000),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_follows (follower_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,followed_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(follower_id,followed_id),CHECK(follower_id<>followed_id));
CREATE TABLE IF NOT EXISTS sports_providers (id TEXT PRIMARY KEY,provider_key TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'unconfigured',last_success_at TEXT,last_error_at TEXT,last_error_code TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sports_fixtures (id TEXT PRIMARY KEY,provider_id TEXT NOT NULL REFERENCES sports_providers(id),external_id TEXT NOT NULL,competition TEXT NOT NULL,home_name TEXT NOT NULL,away_name TEXT NOT NULL,kickoff_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'scheduled',source_updated_at TEXT,fetched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider_id,external_id));
CREATE INDEX IF NOT EXISTS idx_fixtures_kickoff ON sports_fixtures(kickoff_at);
CREATE TABLE IF NOT EXISTS odds_snapshots (id TEXT PRIMARY KEY,fixture_id TEXT NOT NULL REFERENCES sports_fixtures(id) ON DELETE CASCADE,market_key TEXT NOT NULL,selection_key TEXT NOT NULL,odds_decimal REAL NOT NULL CHECK(odds_decimal>1),provider_id TEXT NOT NULL REFERENCES sports_providers(id),source_updated_at TEXT,fetched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS match_results (id TEXT PRIMARY KEY,fixture_id TEXT NOT NULL REFERENCES sports_fixtures(id),home_score INTEGER,away_score INTEGER,result_status TEXT NOT NULL,provider_id TEXT NOT NULL REFERENCES sports_providers(id),source_updated_at TEXT,fetched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(fixture_id,provider_id));
CREATE TABLE IF NOT EXISTS wallet_ledger (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),entry_type TEXT NOT NULL,amount_tzs INTEGER NOT NULL CHECK(amount_tzs>0),reference_type TEXT NOT NULL,reference_id TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY,actor_user_id TEXT REFERENCES users(id),action TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,request_id TEXT,metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
